// SPDX-License-Identifier: Apache-2.0
// Read-only native revision calculation for the already active exact goal.
import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { pathToFileURL } from 'node:url'

const [repositoryRoot, assessmentGoalId] = process.argv.slice(2)
if (!repositoryRoot || !assessmentGoalId) throw new Error('Repository and assessment goal ID required')
const moduleUrl = pathToFileURL(resolve(repositoryRoot, 'app/scripts/lib/learningUnitContracts.ts'))
const { assessmentReviewRevisions } = await import(moduleUrl.href)
const document = JSON.parse(readFileSync(resolve(repositoryRoot,
  'curricula/DE/Gymnasium/canonical/DE_DEU_S_GYM_CANONICAL_PHYSIK.de.json'), 'utf8'))
const goal = document.goals.find((entry: { id: string }) => entry.id === assessmentGoalId)
if (!goal) throw new Error(`Missing current assessment: ${assessmentGoalId}`)
console.log(JSON.stringify({ goalId: assessmentGoalId, ...assessmentReviewRevisions(goal) }))
